RUNNER VARCHAR DEFAULT 'WITH ASSESS_AI_VALUE AS PROCEDURE(CONFIG VARIANT) RETURNS VARIANT LANGUAGE PYTHON RUNTIME_VERSION=''3.11'' PACKAGES=(''snowflake-snowpark-python'') HANDLER=''main'' AS ''def materialize_editable_source(session, database, schema, app_name, solution_key, app_source, files):
    import ast
    import base64
    import hashlib
    import json
    import re

    if any(not re.fullmatch(r"[A-Z_][A-Z0-9_$]*", value) for value in (database, schema, app_name)):
        return {"source_status": "UNSUPPORTED_SOURCE_IDENTIFIER", "edit_source_url": None}
    target = database + "." + schema
    marker = "oneshot-source:" + solution_key
    workspace = target + ".ONESHOT_SOURCE"

    def execute(statement, parameters=None):
        return [row.as_dict() for row in session.sql(statement, params=parameters).collect()]

    try:
        existing = [row for row in execute("SHOW WORKSPACES IN SCHEMA " + target) if row["name"] == "ONESHOT_SOURCE"]
        account = execute("SELECT CURRENT_ORGANIZATION_NAME() ORG, CURRENT_ACCOUNT_NAME() ACCOUNT, CURRENT_ROLE() ROLE")[0]
        url = ("https://app.snowflake.com/" + account["ORG"].lower() + "/" + account["ACCOUNT"].lower()
               + "/#/workspaces/ws/" + database + "/" + schema + "/ONESHOT_SOURCE/streamlit_app.py")
        if existing:
            if len(existing) == 1 and existing[0].get("comment") == marker and existing[0].get("owner") == account["ROLE"]:
                return {"source_status": "EXISTING_SOURCE_PRESERVED", "edit_source_url": url}
            return {"source_status": "SOURCE_WORKSPACE_COLLISION", "edit_source_url": None}
        files = dict(files)
        tree = ast.parse(app_source)
        replacements = []
        for node in tree.body:
            if not isinstance(node, ast.Assign) or len(node.targets) != 1 or not isinstance(node.targets[0], ast.Name):
                continue
            name = node.targets[0].id
            if name in {"PILOT_JS_B64", "PILOT_CSS_B64"} and isinstance(node.value, ast.Constant):
                asset = "assets/app.js" if name == "PILOT_JS_B64" else "assets/style.css"
                files[asset] = base64.b64decode(node.value.value).decode()
                replacements.append((node.lineno, node.end_lineno, ""))
            if name in {"JAVASCRIPT", "STYLES"}:
                asset = "assets/app.js" if name == "JAVASCRIPT" else "assets/style.css"
                replacements.append((node.lineno, node.end_lineno, name + '''' = (Path(__file__).parent / '''' + repr(asset) + '''').read_text()''''))
        lines = app_source.splitlines()
        for start, end, replacement in sorted(replacements, reverse=True):
            lines[start - 1:end] = [replacement]
        source = "from pathlib import Path\\\\n" + "\\\\n".join(lines) + "\\\\n"
        source = source.replace(''''base64.b64decode(PILOT_JS_B64).decode("utf-8")'''', ''''(Path(__file__).parent / "assets/app.js").read_text()'''')
        source = source.replace(''''base64.b64decode(PILOT_CSS_B64).decode("utf-8")'''', ''''(Path(__file__).parent / "assets/style.css").read_text()'''')
        ast.parse(source)
        files["streamlit_app.py"] = source
        revision = hashlib.sha256(source.encode()).hexdigest()[:16]
        metadata = json.loads(files["source.json"])
        runtime_files = [name for name in files if any(name == path or name.startswith(path + "/") for path in metadata["runtime_paths"])]
        runtime_files.append("runtime_config.json")
        runtime_files = sorted(set(runtime_files))
        files["runtime_config.json"] = json.dumps({"target_schema": target, "workspace": workspace,
            "stage": target + ".APP_STAGE", "app": target + "." + app_name,
            "baseline_revision": revision, "baseline_files": sorted(set(runtime_files))})
        format_sql = " FILE_FORMAT=(TYPE=CSV COMPRESSION=NONE FIELD_DELIMITER=NONE RECORD_DELIMITER=NONE FIELD_OPTIONALLY_ENCLOSED_BY=NONE ESCAPE_UNENCLOSED_FIELD=NONE) SINGLE=TRUE OVERWRITE=FALSE"
        for name, content in sorted(files.items()):
            if not re.fullmatch(r"[A-Za-z0-9_./-]+", name) or ".." in name.split("/"):
                raise ValueError("Invalid source path")
            execute("COPY INTO @" + target + ".APP_STAGE/source/" + revision + "/" + name + " FROM (SELECT ?)" + format_sql, [content])
        file_list = ",".join("''''" + name + "''''" for name in sorted(set(runtime_files)))
        execute("COPY FILES INTO @" + target + ".APP_STAGE/releases/" + revision + "/ FROM @" + target + ".APP_STAGE/source/" + revision + "/ FILES=(" + file_list + ")")
        execute("CREATE WORKSPACE " + workspace + " COMMENT=?", [marker])
        execute("ALTER WORKSPACE " + workspace + " ADD LIVE VERSION FROM LAST")
        execute("COPY FILES INTO ''''snow://workspace/" + workspace + "/versions/live/'''' FROM @" + target + ".APP_STAGE/source/" + revision + "/")
        return {"source_status": "AVAILABLE", "edit_source_url": url, "source_revision": revision}
    except Exception as error:
        return {"source_status": "SOURCE_WORKSPACE_UNAVAILABLE", "source_error": str(error)[:1000], "edit_source_url": None}

import base64 as source_base64, json as source_json
PORTABLE_SOURCE_FILES = source_json.loads(source_base64.b64decode(''''''''))
import copy
import hashlib
import json
import math
import re


VERSION = "35.1.0"
SIMPLE_IDENTIFIER = re.compile(r"^[A-Z_][A-Z0-9_$]*$")


def canonical(value):
    return json.dumps(value, sort_keys=True, separators=(",", ":"), ensure_ascii=True, allow_nan=False)


def digest(value):
    return hashlib.sha256(canonical(value).encode()).hexdigest()


def ident(value):
    if not isinstance(value, str) or not value or len(value) > 255 or "\\\\x00" in value:
        raise ValueError("Identifier must be a nonempty component of at most 255 characters")
    return ''''"'''' + value.replace(''''"'''', ''''""'''') + ''''"''''


def relation(components):
    if not isinstance(components, list) or len(components) != 3:
        raise ValueError("A relation must contain three exact identifier components")
    return ".".join(ident(component) for component in components)


def literal(value):
    if value is None:
        return "NULL"
    if isinstance(value, bool):
        return "TRUE" if value else "FALSE"
    if isinstance(value, (float, int)):
        if not math.isfinite(value):
            raise ValueError("Nonfinite setting")
        return str(value)
    return "''''" + str(value).replace("\\\\\\\\", "\\\\\\\\\\\\\\\\").replace("''''", "''''''''") + "''''"


def compatible(data_type, expected):
    data_type = str(data_type).upper().split("(")[0]
    if expected == "text":
        return data_type in {"TEXT", "VARCHAR", "STRING", "CHAR"}
    if expected == "number":
        return data_type in {"NUMBER", "DECIMAL", "NUMERIC", "FLOAT", "DOUBLE", "REAL", "INT", "INTEGER", "BIGINT"}
    if expected == "date":
        return data_type == "DATE" or data_type.startswith("TIMESTAMP")
    return compatible(data_type, "text") or compatible(data_type, "number")


def value_projection(inputs):
    required = ["items", "coverage", "accepted_fraction", "manual_minutes", "review_minutes", "fallback_minutes", "setup_minutes"]
    if any(inputs.get(name) is None for name in required):
        return {"state": "BASELINE_NEEDED", "net_minutes": None, "basis": "Supply workflow volume and human-effort assumptions. Query counts are not labor."}
    values = {name: float(inputs[name]) for name in required}
    if any(not math.isfinite(value) or value < 0 for value in values.values()):
        raise ValueError("Value inputs must be finite and nonnegative")
    if not 0 <= values["coverage"] <= 1 or not 0 <= values["accepted_fraction"] <= 1:
        raise ValueError("Coverage and accepted fraction must be between zero and one")
    eligible = values["items"] * values["coverage"]
    baseline = eligible * values["manual_minutes"]
    assisted = eligible * (values["review_minutes"] + (1 - values["accepted_fraction"]) * values["fallback_minutes"])
    net = baseline - assisted - values["setup_minutes"]
    break_even = None
    if eligible > 0 and values["fallback_minutes"] > 0:
        break_even = 1 - (values["manual_minutes"] - values["review_minutes"] - values["setup_minutes"] / eligible) / values["fallback_minutes"]
    return {"state": "SCENARIO", "eligible_items": eligible, "accepted_items": eligible * values["accepted_fraction"],
            "baseline_minutes": baseline, "assisted_minutes": assisted, "net_minutes": net,
            "break_even_accepted_fraction": break_even, "basis": "Editable assumptions, not observed savings or accuracy. Operating costs excluded; hours are capacity, not cash."}


def evidence_key(asset):
    return digest({"relation": asset["relation"], "columns": asset["columns"], "created_on": asset.get("created_on")})


def assess_asset(solution, asset, profile=None, approval=None, functions=None):
    columns = asset["columns"]
    missing = [name for name in solution["required"] if name not in columns]
    wrong = [name for name, expected in solution["required"].items() if name in columns and not compatible(columns[name], expected)]
    profile = profile or {}
    approval = approval or {}
    functions = functions or {}
    evidence_id = evidence_key(asset)
    approved = approval.get("evidence_id") == evidence_id and approval.get("data_use_approved") is True
    dependencies = []
    improvements = [{"kind": "PARALLEL_IMPROVEMENT", "action": solution["optional"], "owner": "Workflow owner", "test": "Re-run the same reviewed question or item set", "additional_value": "Additional context or coverage; quantify after comparison"}]
    if missing or wrong:
        dependencies.append("Supply an approved projection with the required column names and types: " + ", ".join(missing + wrong))
    if not approved:
        dependencies.append("Confirm this exact relation''''s permitted content, purpose and audience")
    if not profile.get("verified"):
        dependencies.append("Run the separately approved aggregate profile on this source")
    else:
        if profile.get("rows", 0) == 0:
            dependencies.append("Choose a nonempty source slice")
        if profile.get("null_keys", 0) > 0 or profile.get("distinct_keys") != profile.get("rows"):
            dependencies.append("Use a unique, populated item key in the bounded source")
        if profile.get("usable_rows", 0) == 0:
            dependencies.append("Choose a source with usable task input")
    if approval.get("bounded_relation_approved") is not True:
        dependencies.append("Confirm a physically bounded pilot relation; a returned row limit does not cap source scan cost")
    if any(not SIMPLE_IDENTIFIER.fullmatch(component) for component in asset["relation"]):
        dependencies.append("This legacy child needs a simple-uppercase compatibility relation; the assessment itself supports quoted identifiers")
    for function in solution.get("required_ai", []):
        if functions.get(function) is False:
            dependencies.append(function + " is unavailable to the assessed role")
    if solution.get("launch_hold"):
        dependencies.append(solution["launch_hold"])
    if solution.get("current_evidence") != "LIVE_BOUNDED_SYNTHETIC_PASS":
        dependencies.append("Validate the current installer bytes before offering configured launch SQL")
    evidence = "PROFILED" if profile.get("verified") else "METADATA_ONLY"
    if not dependencies:
        decision = "RUN_NARROWER_SCOPE" if not solution.get("required_ai") else "RUN_BOUNDED_PILOT"
    else:
        decision = "RESOLVE_SPECIFIC_DEPENDENCY"
    return {"solution_key": solution["key"], "name": solution["name"], "relation": asset["relation"],
            "evidence_id": evidence_id, "decision": decision, "evidence": evidence, "dependencies": dependencies,
            "improvements": improvements, "missing_columns": missing, "wrong_types": wrong,
            "profile": profile, "output": solution["output"], "limit": solution["limit"],
            "input_coverage": (profile["usable_rows"] / profile["rows"]) if profile.get("verified") and profile.get("rows") else None,
            "source_rows": asset.get("row_count"), "task_quality": "NOT_MEASURED",
            "functions": {name: functions.get(name) for name in solution.get("required_ai", [])},
            "mapping_approved": approved, "pilot_launch_eligible": not dependencies,
            "historical_installer_evidence": solution.get("historical_evidence", {}),
            "current_artifact_evidence": solution.get("current_evidence", "NOT_REVALIDATED"),
            "rank": solution["ranking"]}


def opportunities(registry, assets, profiles=None, approvals=None, functions=None):
    profiles = profiles or {}
    approvals = approvals or {}
    results = []
    for solution in registry["solutions"]:
        required = set(solution["required"])
        ranked = []
        for asset in assets:
            matches = len(required.intersection(asset["columns"]))
            if required and matches < max(1, math.ceil(len(required) / 2)):
                continue
            if not required and len(asset["columns"]) < 2:
                continue
            ranked.append((matches, asset))
        ranked.sort(key=lambda item: (-item[0], relation(item[1]["relation"])))
        for matches, asset in ranked[:3]:
            evidence_id = evidence_key(asset)
            item_key = solution["key"] + ":" + evidence_id
            results.append(assess_asset(solution, asset, profiles.get(item_key), approvals.get(item_key), functions))
        if not ranked:
            results.append({"solution_key": solution["key"], "name": solution["name"], "relation": None,
                            "decision": "RESOLVE_SPECIFIC_DEPENDENCY", "evidence": "NO_VISIBLE_MATCH", "rank": solution["ranking"],
                            "dependencies": [solution["smallest_start"]], "output": solution["output"], "limit": solution["limit"],
                            "pilot_launch_eligible": False, "task_quality": "NOT_MEASURED", "improvements": []})
    return sorted(results, key=lambda item: (not item["pilot_launch_eligible"], item["rank"]))


def configure_installer(template, solution, source, target_database, target_schema, warehouse):
    for component in source + [target_database, target_schema, warehouse]:
        if not SIMPLE_IDENTIFIER.fullmatch(component):
            raise ValueError("Legacy installer requires simple uppercase identifiers")
    if source[:2] == [target_database, target_schema]:
        raise ValueError("Child output schema must differ from the source schema")
    prefix = solution["prefix"]
    settings = copy.deepcopy(solution["settings"])
    settings.update({solution["source_setting"]: ".".join(source), prefix + "_APPROVE": False,
                     prefix + "_TARGET_DB": target_database, prefix + "_SCHEMA": target_schema,
                     prefix + "_APP_WAREHOUSE": warehouse, prefix + "_KEEP_APP_WARM": False,
                     prefix + "_DEPLOY_TIER": "DISCOVER", prefix + "_PROFILE": False,
                     prefix + "_ALLOW_ACTIONS": False})
    for name, value in settings.items():
        pattern = re.compile(r"(?m)^(SET\\\\s+" + re.escape(name) + r"\\\\s*=\\\\s*)(?:''''(?:''''''''|[^''''])*''''|[^;\\\\n]+);", re.IGNORECASE)
        if len(pattern.findall(template)) != 1:
            raise ValueError("Expected exactly one installer setting: " + name)
        template = pattern.sub(lambda match: match.group(1) + literal(value) + ";", template)
    return template

"""
scoring.py — Shared scoring logic for AI Readiness Score.

Provides importable functions used by both the notebook cells and the CLI script.
"""



import math

def classify_gap(pct_demand, n_cr_tables, pct_sv_coverage, avg_sv_quality):
    """Classify the primary improvement gap."""
    if pct_demand is None or n_cr_tables == 0:
        return "BUILD_CR_TABLES"
    if pct_demand < 0.5:
        return "BUILD_CR_TABLES"
    if pct_sv_coverage == 0:
        return "BUILD_SVS"
    if pct_sv_coverage < 0.5:
        return "EXPAND_SV_COVERAGE"
    if avg_sv_quality < 0.5:
        return "IMPROVE_SV_QUALITY"
    return "HEALTHY"


def compute_composite_scores(cr_results, sv_results):
    """
    Compute all AI readiness scores from CR table results and SV quality results.

    Args:
        cr_results: list of dicts from CR tables query (keys lowercase)
        sv_results: list of dicts from SV quality query (keys lowercase)

    Returns:
        dict with all computed scores and metadata
    """
    # Build SV signals map
    sv_signals = {}
    for row in sv_results:
        fqn = str(row.get("sv_fqn") or "")
        if not fqn:
            continue
        if fqn not in sv_signals:
            sv_signals[fqn] = {
                "has_pk": int(row.get("has_pk") or 0),
                "has_synonyms": int(row.get("has_synonyms") or 0),
                "has_unique_keys": int(row.get("has_unique_keys") or 0),
                "has_distinct_ranges": int(row.get("has_distinct_ranges") or 0),
                "has_relationships": int(row.get("has_relationships") or 0),
                "has_metrics": int(row.get("has_metrics") or 0),
                "n_verified_queries": int(row.get("n_verified_queries") or 0),
                "avg_comment_length": float(row.get("avg_comment_length") or 0),
                "quality_score": float(row.get("quality_score") or 0),
                "base_tables": [],
            }
        sv_signals[fqn]["base_tables"].append({
            "database": str(row.get("base_database") or ""),
            "schema": str(row.get("base_schema") or ""),
            "table": str(row.get("base_table") or ""),
        })

    # Identify consumption-ready tables
    all_scored = cr_results
    cr_tables = [r for r in all_scored if float(r.get("consumption_readiness_score") or 0) >= 0.80]
    cr_set = {(r["database_name"], r["schema_name"], r["table_name"]) for r in cr_tables}

    # Demand coverage
    total_reads = sum(int(r.get("analytical_reads") or 0) for r in all_scored)
    reads_on_cr = sum(
        int(r.get("analytical_reads") or 0) for r in all_scored
        if (r["database_name"], r["schema_name"], r["table_name"]) in cr_set
    )
    pct_demand = (reads_on_cr / total_reads) if total_reads >= 10 else None

    # SV coverage
    sv_covered = {
        (bt["database"], bt["schema"], bt["table"])
        for sig in sv_signals.values()
        for bt in sig.get("base_tables", [])
        if (bt["database"], bt["schema"], bt["table"]) in cr_set
    }
    n_sv_covered = len(sv_covered)
    pct_sv_coverage = n_sv_covered / len(cr_set) if cr_set else 0.0

    # SV quality (average across relevant SVs)
    relevant_fqns = {
        fqn for fqn, sig in sv_signals.items()
        if any((bt["database"], bt["schema"], bt["table"]) in cr_set for bt in sig.get("base_tables", []))
    }
    avg_sv_quality = (
        sum(sv_signals[f]["quality_score"] for f in relevant_fqns) / len(relevant_fqns)
        if relevant_fqns else 0.0
    )

    # Composite scores
    dc_100 = (pct_demand or 0.0) * 100
    sv_cov_100 = pct_sv_coverage * 100
    sv_qual_100 = avg_sv_quality * 100
    sv_readiness = math.sqrt(pct_sv_coverage * avg_sv_quality) * 100
    ai_readiness = ((pct_demand or 0.0) + math.sqrt(pct_sv_coverage * avg_sv_quality)) / 2.0 * 100

    gap = classify_gap(pct_demand, len(cr_set), pct_sv_coverage, avg_sv_quality)

    # Missing dimensions
    missing_dims = [
        label for flag, label in [
            ("has_pk", "primary keys"),
            ("has_synonyms", "synonyms"),
            ("has_metrics", "metrics"),
            ("has_relationships", "relationships"),
        ]
        if relevant_fqns and sum(sv_signals[f][flag] for f in relevant_fqns) / len(relevant_fqns) < 0.5
    ]

    # Improvement items — scoped to the primary gap (mirrors dbt pipeline logic)
    sv_covered_set = set()
    for sig in sv_signals.values():
        for bt in sig.get("base_tables", []):
            key = (bt["database"], bt["schema"], bt["table"])
            if key in cr_set:
                sv_covered_set.add(key)

    items = []
    top_targets = []

    if gap == "BUILD_CR_TABLES":
        # SCHEMA_GAP: schemas with heavy reads but low CR coverage
        from collections import defaultdict
        schema_stats = defaultdict(lambda: {"total_reads": 0, "tables_read": 0, "cr_tables": 0, "cr_reads": 0})
        for r in all_scored:
            key = (r["database_name"], r["schema_name"])
            reads = int(r.get("analytical_reads") or 0)
            schema_stats[key]["total_reads"] += reads
            schema_stats[key]["tables_read"] += 1
            if (r["database_name"], r["schema_name"], r["table_name"]) in cr_set:
                schema_stats[key]["cr_tables"] += 1
                schema_stats[key]["cr_reads"] += reads

        schema_items = []
        for (db, schema), stats in schema_stats.items():
            if stats["total_reads"] < 10:
                continue
            uncovered_reads = stats["total_reads"] - stats["cr_reads"]
            schema_items.append({
                "type": "SCHEMA_GAP",
                "target": f"{db}.{schema}",
                "detail": f"{stats[''''total_reads'''']:,} reads across {stats[''''tables_read'''']} tables, {stats[''''cr_tables'''']} CR",
                "recommendation": f"Increase CR coverage — {uncovered_reads:,} reads land on non-CR tables.",
                "_sort_key": uncovered_reads,
            })
        schema_items.sort(key=lambda x: x["_sort_key"], reverse=True)
        for item in schema_items[:10]:
            del item["_sort_key"]
            items.append(item)

        # top_targets = top schemas by uncovered reads (for NL paragraph)
        top_targets = [item["target"] for item in items[:5]]

    elif gap in ("BUILD_SVS", "EXPAND_SV_COVERAGE"):
        # UNCOVERED_CR_TABLE: CR tables without any semantic view
        uncovered = [
            r for r in all_scored
            if (r["database_name"], r["schema_name"], r["table_name"]) in cr_set
            and (r["database_name"], r["schema_name"], r["table_name"]) not in sv_covered_set
        ]
        uncovered.sort(key=lambda r: int(r.get("analytical_reads") or 0), reverse=True)
        for r in uncovered[:10]:
            items.append({
                "type": "UNCOVERED_CR_TABLE",
                "target": f"{r[''''database_name'''']}.{r[''''schema_name'''']}.{r[''''table_name'''']}",
                "detail": f"{int(r.get(''''analytical_reads'''') or 0):,} reads, {int(r.get(''''distinct_users'''') or 0)} distinct users",
                "recommendation": "Create a semantic view for this table.",
            })

        # top_targets = top uncovered CR tables (for NL paragraph)
        top_targets = [item["target"] for item in items[:5]]

    elif gap == "IMPROVE_SV_QUALITY":
        # SV_QUALITY_GAP: SVs covering CR tables with quality < 0.5
        relevant_svs = [
            (fqn, sig) for fqn, sig in sv_signals.items()
            if any((bt["database"], bt["schema"], bt["table"]) in cr_set for bt in sig.get("base_tables", []))
            and sig["quality_score"] < 0.5
        ]
        relevant_svs.sort(key=lambda x: x[1]["quality_score"])
        for fqn, sig in relevant_svs[:10]:
            missing = []
            if not sig["has_pk"]:
                missing.append("primary key")
            if not sig["has_synonyms"]:
                missing.append("synonyms")
            if not sig["has_metrics"]:
                missing.append("metrics")
            if not sig["has_relationships"]:
                missing.append("relationships")
            if not sig["has_unique_keys"]:
                missing.append("unique keys")
            if not sig["n_verified_queries"]:
                missing.append("verified queries")
            items.append({
                "type": "SV_QUALITY_GAP",
                "target": fqn,
                "detail": f"Quality: {sig[''''quality_score''''] * 100:.0f}/100",
                "recommendation": f"Add: {'''', ''''.join(missing[:4])}." if missing else "Improve SV metadata.",
            })

    # HEALTHY: no items needed (account is in good shape)

    return {
        "ai_readiness": round(ai_readiness, 2),
        "demand_coverage": round(dc_100, 2),
        "sv_readiness": round(sv_readiness, 2),
        "sv_coverage": round(sv_cov_100, 2),
        "sv_quality": round(sv_qual_100, 2),
        "n_cr_tables": len(cr_set),
        "gap": gap,
        "top_targets": top_targets,
        "missing_dims": missing_dims,
        "n_all_scored": len(all_scored),
        "n_sv": len(sv_signals),
        "n_sv_covered": n_sv_covered,
        "pct_demand_raw": pct_demand,
        "pct_sv_coverage_raw": pct_sv_coverage,
        "avg_sv_quality_raw": avg_sv_quality,
        "improvement_items": items,
    }

import base64
import datetime
